Definition r_AST_85_0000 : list(option Trans) := [t1RB;t1RC;t1LC;t1RA;t1LD;t0RA;t1RA;t0LB].
Local Definition tm := row_to_tm r_AST_85_0000.
Local Lemma recurrent : forall N,exists j,N<=j /\ FiresAt tm(StD,S0)j.
Proof.
 apply(sweep_reset_D0_recurrent tm);try(vm_compute;reflexivity).
 exists 8,(srU 0).
 assert(E:exists c,csteps tm 8 c0=Some c /\ ceqb c(sr_anchor(srU 0))=true).
 { eexists;split;vm_compute;reflexivity. }
 destruct E as(c&Ec&El). rewrite <-lift_c0.
 rewrite(csteps_lift _ _ _ _ Ec),(ceqb_lift _ _ El);reflexivity.
Qed.
Lemma cv_AST_85_0000 : coversTr(row_to_tm r_AST_85_0000).
Proof.
 apply coversTr_nqh,neverqhtr_mirror.
 apply(ngram_check_neverqh_fuelmixtr_except_sound (mirror_tm tm) 4 0 3848 29 skipD0 cert_AST_85_0000).
 - intros [[] []] H N;try discriminate. destruct(recurrent N)as(j&Hj&Ej).
   exists j. split;[exact Hj|apply mirror_fires;exact Ej].
 - vm_compute;reflexivity.
Qed.
